<script setup lang="ts">
import {computed,onMounted,ref,nextTick} from 'vue'
import {api} from '../api'
import {number,time} from '../format'
import {roleName} from '../templates'
import type {TemplateIndex,TemplateCase,ChartPoint} from '../templates'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import ResearchChart from '../components/ResearchChart.vue'
const index=ref<TemplateIndex|null>(null);const current=ref<TemplateCase|null>(null);const query=ref('');const group=ref('all');const error=ref('');const loading=ref(false);let request=0
async function select(key:string,scroll=true){const seq=++request;loading.value=true;error.value='';try{const r=await api<TemplateCase>(`/api/research/templates/${encodeURIComponent(key)}`);if(seq===request){current.value=r;if(scroll){await nextTick();document.getElementById('template-detail')?.scrollIntoView({behavior:'smooth',block:'start'})}}}catch(e){if(seq===request)error.value=e instanceof Error?e.message:String(e)}finally{if(seq===request)loading.value=false}}
onMounted(async()=>{try{index.value=await api('/api/research/templates');const first=index.value?.cases.find(c=>c.symbol==='TRBUSDT'&&c.status==='observed')??index.value?.cases[0];if(first)await select(first.key,false)}catch(e){error.value=String(e)}})
const rows=computed(()=>index.value?.cases.filter(c=>c.symbol.toLowerCase().includes(query.value.trim().toLowerCase())&&(group.value==='all'||group.value==='controls'&&['market-control','crash-context','delisting-context'].includes(c.role)||group.value==='patterns'&&['seed','seed-contrast','historical'].includes(c.role)))??[])
const valid=computed(()=>index.value?.cases.filter(c=>c.status==='observed')??[])
const unique=computed(()=>new Set(index.value?.cases.map(c=>c.symbol)).size)
const price=computed<ChartPoint[]>(()=>current.value?.timeline?.map(r=>({t:Date.parse(r.time),v:Number(r.close),low:Number(r.low),high:Number(r.high)}))??[])
const oi=computed<ChartPoint[]>(()=>current.value?.oiTimeline?.map(r=>({t:Date.parse(r.time),v:Number(r.quantity)}))??[])
const funding=computed<ChartPoint[]>(()=>current.value?.fundingTimeline?.map(r=>({t:Date.parse(r.time),v:Number(r.rate)*100}))??[])
const volume=computed<ChartPoint[]>(()=>current.value?.timeline?.map(r=>({t:Date.parse(r.time),v:Number(r.quoteVolume)}))??[])
const taker=computed<ChartPoint[]>(()=>current.value?.timeline?.filter(r=>r.takerBuyBaseShare!=null).map(r=>({t:Date.parse(r.time),v:r.takerBuyBaseShare!*100}))??[])
const mark=computed<ChartPoint[]>(()=>current.value?.markTimeline?.map(r=>({t:Date.parse(r.time),v:Number(r.close),low:Number(r.low),high:Number(r.high)}))??[])
const peak=computed(()=>Date.parse(current.value?.peak??''));const event=computed(()=>current.value?.eventTime?Date.parse(current.value.eventTime):undefined);const start=computed(()=>current.value?.chartStart?Date.parse(current.value.chartStart):peak.value-72*3600000);const end=computed(()=>current.value?.chartEnd?Date.parse(current.value.chartEnd):peak.value+73*3600000)
const pct=(n:number|null|undefined)=>n==null?'Unknown':`${number(n,2)}%`
</script><template><PageIntro eyebrow="HISTORICAL TEMPLATES · MULTI-EVIDENCE" title="看懂相似行情，保留不同证据。" description="先建立历史行为样板，再检验提前观察与涨幅榜机会。这里不直接产生开仓指令。"/><p v-if="error" class="radar-notice" role="alert">{{error}}</p><p class="radar-notice">形态标签描述可观察行为，不证明某个主体操纵、吸筹或出货。底部与峰值由事后选取，涨幅不是可执行收益；小时内高低先后不明。资金费、OI只在已取得区间展示；历史持币人数和已核对钱包仍缺失。自动交易关闭。</p>
<div class="stats"><StatCard label="合约 / 预选时段" :value="`${unique} / ${index?.cases.length??0}`" foot="有意挑选的案例库，不代表全市场"/><StatCard label="通过校验的小时K线" :value="number(valid.reduce((n,c)=>n+(c.hours??0),0),0)" foot="期货原生合约，保留缺口和不同年份"/><StatCard label="具备事件窗口OI" :value="valid.filter(c=>(c.oiRows??0)>0).length" foot="OI数量与美元价值分开，不回填当前值"/><StatCard label="档案校验" :value="index?.archive.verifiedFiles??0" :foot="`SHA256通过 · 缺失 ${index?.archive.missingFiles??0} / 异常 ${index?.archive.unavailableFiles??0}`"/></div>
<div id="template-list" class="market-panel"><div class="toolbar"><label class="search"><input v-model="query" aria-label="搜索历史样板" placeholder="TRB、MYX、YFI、UNFI…"></label><select v-model="group" aria-label="样板类别"><option value="all">全部样板</option><option value="patterns">行情形态</option><option value="controls">市场 / 急跌 / 退市对照</option></select><span>{{rows.length}} 个时段</span></div><div class="table-scroll"><table><thead><tr><th>合约 / 背景</th><th>峰值小时（上海时间）</th><th>事后起点→最高价</th><th>峰值小时之后最低价回落</th><th>峰值小时起点前24h OI数量</th><th>行为标签 / 查看</th></tr></thead><tbody><tr v-for="c in rows" :key="c.key"><td>{{c.symbol}}<small>{{roleName(c.role)}} · {{c.key.slice(-7)}}</small></td><td>{{time(c.peak)}}<small>{{c.hours??0}}小时 · 缺口{{c.gaps??'Unknown'}}</small></td><td>{{pct(c.riseToPeakHighPercent)}}<small>事后标签，非策略收益</small></td><td>{{pct(c.postPeakMinLowPercent)}}<small>{{c.postPeak14dAvailable?'随后14日':'随后可用区间，右侧截断'}}</small></td><td>{{pct(c.oiQuantityChange24hAtPeakPercent)}}</td><td class="decision-reason"><span>{{c.status==='observed'?c.tags?.join(' · '):'数据不足 / 未通过校验'}}</span><button class="text-button" @click="select(c.key)">查看样板 →</button></td></tr></tbody></table></div></div>
<p v-if="loading" role="status">读取已保存的样板…</p><section v-if="current" id="template-detail" class="detail"><h2>{{current.symbol}} · {{roleName(current.role)}}</h2><a href="#template-list">返回样板列表 ↑</a><p>预选范围 {{time(current.period?.[0])}}～{{time(current.period?.[1])}} · {{current.venue}}。选段起点 {{time(current.start)}}，峰值所在小时 {{time(current.peak)}}。急跌/退市背景按最大小时收盘跌幅之前7日的高点锚定，其他按预选范围最高价锚定。</p><p>价格高点、上影线及小时内最低价不能证明真实成交先后。黄线是事后选段高点小时起点；红线如有，为该预选范围最大单小时收盘/开盘跌幅的小时起点。图表覆盖高点与急跌事件两端前后72小时，共享时间轴，缺口断线。</p><template v-if="current.status==='observed'"><ResearchChart title="小时收盘价与高低范围 · 峰值 / 急跌事件选段" :points="price" :start="start" :end="end" :peak="peak" :event="event" :max-gap="5400000"/><ResearchChart title="小时成交额 USDT · 单交易所原始记录，非可成交深度" :points="volume" :start="start" :end="end" :peak="peak" :event="event" :max-gap="1" bars/><ResearchChart title="OI合约数量 · 事件窗口实测（不是美元OI）" :points="oi" :start="start" :end="end" :peak="peak" :event="event" :max-gap="450000"/><ResearchChart title="实际结算资金费率 % · 正负分别展示" :points="funding" :start="start" :end="end" :peak="peak" :event="event" :max-gap="1" bars/><ResearchChart v-if="mark.length" title="历史标记价格 · 不等同于成交价或保证未强平" :points="mark" :start="start" :end="end" :peak="peak" :event="event" :max-gap="5400000"/>
<details><summary>展开主动买入占比（不是资金净流入）</summary><ResearchChart title="主动买入合约量 / 总成交合约量 %" :points="taker" :start="start" :end="end" :peak="peak" :event="event" :max-gap="5400000"/><p>这是已成交合约量的主动方向占比，不能单独判断开仓/平仓，也不能解释为链上资金净流入。</p></details><h3>分开看事实和推断</h3><p v-if="current.eventTime">最大单小时跌幅事件 {{time(current.eventTime)}}；它可能晚于选段高点。图表保留两者，避免只展示危机之前的行情。</p><p>OI比较时点 {{time(current.oiComparisonTimes?.[0])}} → {{time(current.oiComparisonTimes?.[1])}}；数量变化 {{pct(current.oiQuantityChange24hAtPeakPercent)}}。选定上升区间含峰值小时的结算费率合计 {{pct(current.sumFundingRisePercent)}}，共{{current.fundingRiseRows??0}}次，结算周期{{current.fundingIntervals?.join('/')}}h；它不是你的账户资金费成本。</p><p>已观测最大单小时高低范围/开盘价 {{pct(current.maxHourlyHighLowRangePercent)}}，发生于 {{time(current.maxRangeHour)}}；不能从小时柱判断10倍仓位是否能安全穿过。</p><p v-for="m in current.marketComparisons" :key="m.symbol">同一选段起止小时收盘对照 {{m.symbol}}：{{pct(m.closeReturnPercent)}}；本合约收盘变化相对差 {{number(m.relativeCloseMovePp,2)}} 个百分点。仍不是因果证明。</p><h3>突破失败对照 · 预先定义的机械标签</h3><p>本时段发现{{current.breakoutTriggers??0}}个“收盘突破前72h高点0.2%且量≥前24h中位数1.5倍”的研究触发，每24h最多取一次。其中{{current.failedBreakoutLabels??0}}个在随后24h最高涨幅不足5%且最终回到原区间下方。只用于对照，触发与失败阈值尚未样本外验证，不是交易胜率。</p><div class="table-scroll"><table><thead><tr><th>触发收盘时间</th><th>当时已确认支撑候选</th><th>次小时开盘到支撑距离</th><th>随后24h最高 / 最低变化</th></tr></thead><tbody><tr v-for="f in current.failureExamples" :key="f.time"><td>{{time(f.time)}}</td><td>{{f.confirmedSupportCandidate??'Unknown'}}</td><td>{{pct(f.supportDistancePercent)}}</td><td>{{pct(f.forward24hMaxHighPercent)}} / {{pct(f.forward24hMinLowPercent)}}</td></tr></tbody></table></div><p>支撑候选在触发时已用右侧两根闭合K线确认；尚未加入波动缓冲、成交费用、分批退出和强平约束，不是执行止损价。</p><h3>仍缺少的证据</h3><p>历史持币人数、筹码归属、项目钱包转账及消息催化未核实，不将“负费率＋拉升”直接认定为逼空操纵，也不将长上影直接认定为项目方出货。</p></template><p v-else>此案例数据不完整，保留在样本清单中，不因失败或退市而删除。{{current.errorType}}</p></section><p>数据来源：<a href="https://github.com/binance/binance-public-data" target="_blank" rel="noreferrer">Binance公开历史档案 ↗</a>，逐文件校验SHA256。<br>生成 {{time(index?.generatedAt)}} · <RouterLink to="/strategy-research">查看两套策略的研究口径 →</RouterLink></p></template>
